from .core import Vault, gate

@patch
def pii(self:Vault,
        ref,                 # a doc_id, source, title or path: whatever `document` takes
        max_chars:int=MAX_SCAN,
        ner:bool=False,      # also look for names that follow a title such as Dr; never on code
) -> AttrDict:
    "Report whether one document holds personal information, which kinds, and any mark that overrides the detector."
    d = self.document(ref, max_chars=max_chars)
    prose = (d.get('kind') or '') != 'code'
    # `scanned_ner` reports False for code, because no name pass ran
    r = pii_report(d.text, ner=ner and prose)
    override = (self.marks(d.get('doc_id')) or {}).get('pii_override') if d.get('doc_id') else None
    r.detected, r.override = r.has_pii, override
    if override == 'clear': r.has_pii = False
    elif override in ('force', 'local'): r.has_pii = True
    r.doc_id, r.title, r.source = d.get('doc_id'), d.get('title'), d.get('source')
    return r

@patch
def mark_not_pii(self:Vault, ref, clear:bool=True, reason:str='', by:str='person') -> dict:
    "Mark a document as not personal, or with `clear=False` hand the decision back to the detector; only a person may do either."
    _person(by, 'clear a mark')
    return self.mark(ref, pii_override='clear' if clear else None,
                     pii_reason=(reason or None) if clear else None)

@patch
def mark_pii(self:Vault, ref, force:bool=True, reason:str='', by:str='person') -> dict:
    "Mark a document as personal when the detector finds nothing, or remove that mark with `force=False`, which only a person may do."
    if not force: _person(by, 'clear a mark')
    return self.mark(ref, pii_override='force' if force else None,
                     pii_reason=(reason or None) if force else None)

def pii_ctx(ctx, ner:bool=False) -> AttrDict:
    "Run the detector over every section in an assembled context: its text, heading, title and source."
    get = lambda r, f: getattr(r, f, None) or (r.get(f) if isinstance(r, dict) else None)
    parts = [s for r in (list(ctx.get('results') or []) + list(ctx.get('related') or []))
             for s in dict.fromkeys(str(get(r, f) or '') for f in ('text', *ROW_LABEL, *ROW_META)) if s]
    return pii_report('\n\n'.join(parts), ner=ner)

# %% ../nbs/09_pii.ipynb #8361cd32
GATES = ('off', 'redact', 'refuse')
ROW_TEXT = ('text', 'snippet', 'snippets', 'content', 'summary')
ROW_LABEL = ('title', 'breadcrumb')
ROW_META = ('source', 'sources', 'filename')   # `sources`: every path litesearch filed a document's text under
ROW_KIDS = ('tree', 'children')
CTX_ROWS = ('results', 'related', 'docs', 'hits')

def _pii_marks(v):
    "Cleared and force-private `(store, doc_id)` pairs, for whichever gate is asking. A local-only mark is private."
    if not v._marks().exists(): return set(), set()
    rows = list(v._marks()(where="pii_override IN ('clear','force','local')"))
    return ({(r['store'], r['doc_id']) for r in rows if r['pii_override'] == 'clear'},
            {(r['store'], r['doc_id']) for r in rows if r['pii_override'] in ('force', 'local')})

def _level_sets(v):
    "Cleared, private and local-only `(store, doc_id)` pairs, and the shelf's floor. A floor above open voids `clear`."
    cleared, forced = _pii_marks(v)
    fl, sens = v.floor(), [k for k, p in TYPE_POLICY.items() if p.get('level') == 'local']
    local = {(r['store'], r['doc_id']) for r in v._marks()(where="pii_override='local'")} if v._marks().exists() else set()
    typed = {(v.name, r['id']) for r in v.t.docs(select='id', where_args=sens,
             where=f"json_extract(meta,'$.doctype') IN ({','.join('?' * len(sens))})")}
    return (cleared if fl == 'open' else set()), forced, local | (typed - cleared - forced), fl

def _row_get(r, k): return r.get(k) if isinstance(r, dict) else getattr(r, k, None)

def _row_doc(r):
    "The document a row belongs to. A row that names none falls back to its own text."
    # `search` and `context` say `doc_id`, `sections` only `node_id`, `read` says `id`, `federate` `ref`
    for k in ('doc_id', 'node_id', 'id', 'ref'):
        if v := _row_get(r, k): return str(v).split('#', 1)[0]

def _row_key(r, store):
    did = _row_doc(r)
    return (_row_get(r, 'store') or store, did) if did else None

def _row_kinds(r, cleared, forced, store, ner=False):
    "What one row holds, honouring the mark on its document. `None` when it holds nothing."
    key = _row_key(r, store)
    if key and key in cleared: return None
    if key and key in forced: return {'marked': 1}
    parts = []
    for f in (*ROW_TEXT, *ROW_LABEL, *ROW_META):
        v = _row_get(r, f)
        parts += [str(x) for x in v] if isinstance(v, (list, tuple)) else ([str(v)] if v else [])
    rep = pii_report('\n\n'.join(parts), ner=ner)
    return dict(rep.identifying) if rep.has_pii else None

def _section_private(r, cleared, forced, store:str, ner:bool=False) -> bool:
    "Whether one retrieved section is somebody's business. What `ask` filters its context on."
    return bool(_row_kinds(r, cleared, forced, store, ner))

def held(kinds) -> str:
    "The placeholder that replaces withheld text: it names the kinds found, or says the document is local only."
    if 'local' in kinds: return '[withheld: local only]'
    return f"[withheld: personal information ({', '.join(sorted(kinds))})]"

def _mask(r, f, fix):
    "Rewrite field `f` of `r` through `fix`, whether it holds a string or a list of them."
    if not (v := r.get(f)): return
    r[f] = type(v)(fix(str(x)) for x in v) if isinstance(v, (list, tuple)) else fix(str(v))

def _gate_row(r, act, cleared, forced, store, ner, local=frozenset(), floor='open'):
    "One row masked or withheld, and whatever nests under it. A local-only row is withheld under either mode, its title, breadcrumb and source with its text."
    if not isinstance(r, dict): return r
    kinds = _row_kinds(r, cleared, forced, store, ner)
    if loc := floor == 'local' or _row_key(r, store) in local: kinds, act = {'local': 1}, 'refuse'
    elif floor == 'personal' and not kinds: kinds = {'floor': 1}
    kids = {f: v for f in ROW_KIDS if isinstance(v := r.get(f), (dict, list, tuple, L))}
    if not kinds and not kids: return r
    out = type(r)(r)
    label = lambda s: redact(s, ner=ner)
    if kinds:
        hide = lambda s: held(kinds)
        for f in ROW_TEXT: _mask(out, f, label if act == 'redact' else hide)
        for f in (*ROW_LABEL, *ROW_META): _mask(out, f, hide if loc else label)
        out['pii'] = kinds
    g = lambda x: _gate_row(x, act, cleared, forced, store, ner, local, floor)
    for f, v in kids.items(): out[f] = g(v) if isinstance(v, dict) else type(v)(g(k) for k in v)
    return out

def gated(o,                  # whatever a retrieval primitive returned
          pii:str='off',      # off | redact | refuse
          vault=None,         # the shelf whose marks apply; None -> no marks
          ner:bool=False,     # also mask names that follow a title such as Dr
          store:str=None,     # the shelf the rows came from; None -> the vault's own
):
    "Apply a retrieval policy, `off`, `redact` or `refuse`, to search rows, an assembled context, one section or a string."
    if pii == 'off' or o is None: return o
    if pii not in GATES: raise ValueError(f'unknown pii policy for retrieval: {pii!r}; one of {GATES}')
    cleared, forced, local, fl = _level_sets(vault) if vault is not None else (set(), set(), set(), 'open')
    g = lambda r: _gate_row(r, pii, cleared, forced, store or getattr(vault, 'name', 'store'), ner, local, fl)
    if isinstance(o, str):
        rep = pii_report(o, ner=ner)
        if not rep.has_pii: return o
        return redact(o, ner=ner) if pii == 'redact' else held(rep.identifying)
    if isinstance(o, (list, tuple, L)): return type(o)(g(r) for r in o)
    if not isinstance(o, dict): return o
    rows = [k for k in CTX_ROWS if isinstance(o.get(k), (list, tuple, L))]
    if not rows and not isinstance(o.get('doc'), dict): return g(o)
    out = type(o)(o)
    for k in rows: out[k] = L(g(r) for r in out[k])
    if isinstance(out.get('doc'), dict): out['doc'] = g(out['doc'])
    return out


